            }
            
            // Update cart display
            updateCartDisplay();
        });
    });
    
    function updateCartDisplay() {
        // Clear current cart
        cartList.innerHTML = '';
        
        // Add each item to cart
        for (const name in cart) {
            const item = cart[name];
            const li = document.createElement('li');
            li.textContent = `${name} x${item.count}`;
            cartList.appendChild(li);
        }
    }
