#!/usr/bin/env python3

import sys
sys.path.append('.')

from q6_jpath import get, set_path

# Test data
data = {
    "a": {
        "b": [1, 2, {"c": "value"}]
    }
}

print("Testing q6_jpath get() function with default parameter...")

# Test 1: Path that exists - should return the value
try:
    result = get(data, "a.b.0")
    print(f"Test 1 - get(data, 'a.b.0'): {result} (expected: 1)")
    assert result == 1
    print("PASS: Test 1 passed")
except Exception as e:
    print(f"FAIL: Test 1 failed: {e}")

# Test 2: Path that exists with default - should return the value
try:
    result = get(data, "a.b.2.c", "default_value")
    print(f"Test 2 - get(data, 'a.b.2.c', 'default_value'): {result} (expected: value)")
    assert result == "value"
    print("PASS: Test 2 passed")
except Exception as e:
    print(f"FAIL: Test 2 failed: {e}")

# Test 3: Path that doesn't exist without default - should raise KeyError
try:
    result = get(data, "a.b.5")
    print(f"FAIL: Test 3 failed: Should have raised KeyError but got {result}")
except KeyError as e:
    print(f"Test 3 - get(data, 'a.b.5') raised KeyError as expected: {e}")
    print("PASS: Test 3 passed")
except Exception as e:
    print(f"FAIL: Test 3 failed: Wrong exception type {type(e).__name__}: {e}")

# Test 4: Path that doesn't exist with default - should return default
try:
    result = get(data, "a.b.5", "default_value")
    print(f"Test 4 - get(data, 'a.b.5', 'default_value'): {result} (expected: default_value)")
    assert result == "default_value"
    print("PASS: Test 4 passed")
except Exception as e:
    print(f"FAIL: Test 4 failed: {e}")

# Test 5: Non-existent key without default - should raise KeyError
try:
    result = get(data, "a.x")
    print(f"FAIL: Test 5 failed: Should have raised KeyError but got {result}")
except KeyError as e:
    print(f"Test 5 - get(data, 'a.x') raised KeyError as expected: {e}")
    print("PASS: Test 5 passed")
except Exception as e:
    print(f"FAIL: Test 5 failed: Wrong exception type {type(e).__name__}: {e}")

# Test 6: Non-existent key with default - should return default
try:
    result = get(data, "a.x", "default_value")
    print(f"Test 6 - get(data, 'a.x', 'default_value'): {result} (expected: default_value)")
    assert result == "default_value"
    print("PASS: Test 6 passed")
except Exception as e:
    print(f"FAIL: Test 6 failed: {e}")

print("\nAll get() tests completed!")

print("\nTesting q6_jpath set_path() function...")

# Test 1: Set a value in existing path
try:
    test_data = {
        "a": {
            "b": [1, 2, {"c": "value"}]
        }
    }
    result = set_path(test_data, "a.b.0", "new_value")
    print(f"Test 1 - set_path(data, 'a.b.0', 'new_value'): {result}")
    assert result["a"]["b"][0] == "new_value"
    print("PASS: Test 1 passed")
except Exception as e:
    print(f"FAIL: Test 1 failed: {e}")

# Test 2: Set a value in nested dict that doesn't exist yet
try:
    test_data = {
        "a": {
            "b": [1, 2, {"c": "value"}]
        }
    }
    result = set_path(test_data, "a.d.e", "new_value")
    print(f"Test 2 - set_path(data, 'a.d.e', 'new_value'): {result}")
    assert result["a"]["d"]["e"] == "new_value"
    print("PASS: Test 2 passed")
except Exception as e:
    print(f"FAIL: Test 2 failed: {e}")

# Test 3: Set a value in new list index
try:
    test_data = {
        "a": {
            "b": [1, 2, {"c": "value"}]
        }
    }
    result = set_path(test_data, "a.b.3", "new_value")
    print(f"Test 3 - set_path(data, 'a.b.3', 'new_value'): {result}")
    assert result["a"]["b"][3] == "new_value"
    print("PASS: Test 3 passed")
except Exception as e:
    print(f"FAIL: Test 3 failed: {e}")

# Test 4: Set a value in existing list index that's out of bounds
try:
    test_data = {
        "a": {
            "b": [1, 2, {"c": "value"}]
        }
    }
    result = set_path(test_data, "a.b.5", "new_value")
