except IndexError as e:
    print(f"Test 4 - set_path(data, 'a.b.5', 'new_value') raised IndexError as expected: {e}")
    print("PASS: Test 4 passed")
except Exception as e:
    print(f"FAIL: Test 4 failed: Wrong exception type {type(e).__name__}: {e}")

# Test 5: Set a value in non-indexable type
try:
    test_data = {
        "a": {
            "b": "not_a_list"
        }
    }
    result = set_path(test_data, "a.b.0", "new_value")
