class TextBuffer {
  constructor(text = '') {
    this._text = text;
    this._history = [];
    this._historyPointer = -1;
  }
  
  text() {
    return this._text;
  }
  
  lines() {
    return this._text.split('\n');
  }
  
  lineCol(pos) {
    if (pos < 0 || pos > this._text.length) {
      throw new Error('Position out of bounds');
    }
    
    let line = 0;
    let col = 0;
    let currentPos = 0;
    
    while (currentPos < pos) {
      if (this._text[currentPos] === '\n') {
        line++;
        col = 0;
      } else {
        col++;
      }
      currentPos++;
    }
    
    return { line, col };
  }
  
  posOf(line, col) {
    if (line < 0 || col < 0) {
      throw new Error('Line and column must be non-negative');
    }
    
    let currentLine = 0;
    let currentCol = 0;
    let pos = 0;
    
    // Skip to the start of the requested line
    while (currentLine < line) {
      if (pos >= this._text.length) {
        throw new Error('Line out of bounds');
      }
      if (this._text[pos] === '\n') {
        currentLine++;
      }
      pos++;
    }
    
    // Skip to the requested column in that line
    while (currentCol < col) {
      if (pos >= this._text.length) {
        throw new Error('Column out of bounds');
      }
      if (this._text[pos] === '\n') {
        throw new Error('Column out of bounds');
      }
      pos++;
      currentCol++;
    }
    
    return pos;
  }
  
