#!/usr/bin/env python3

import sys
sys.path.append('.')

from q8_units import parse_quantity

def test_parse_quantity():
    # Test cases from the goal
    test_cases = [
        ('2 kg', (2.0, 'kg')),
        ('0.5 l', (0.5, 'l')),
        ('3/4 cup', (0.75, 'cup')),
        ('1 1/2 cups', (1.5, 'cup')),
    ]
    
    for text, expected in test_cases:
        try:
            result = parse_quantity(text)
            print(f"parse_quantity('{text}') = {result}")
