  buffer1.lineCol(-1);
  console.assert(false, "lineCol should throw error for negative position");
} catch (e) {
  console.assert(e.message === "Position out of bounds", "lineCol should throw correct error for negative position");
}

try {
  buffer1.lineCol(20);
