      if (tag.startsWith('if')) {
        // Handle if statement
        const condition = tag.substring(2).trim();
        if (data[condition]) {
          // Find matching endif
          let k = j + 1;
          let nested = 0;
          while (k < template.length) {
            if (template[k] === '<' && template[k+1] === '/') {
              if (template.substring(k, k+6) === '</if>') {
                if (nested === 0) {
                  result += render(template.substring(j+1, k), data);
                  i = k + 5;
                  break;
                }
                nested--;
              }
            } else if (template[k] === '<' && template[k+1] !== '/') {
              if (template.substring(k, k+3) === '<if') {
                nested++;
              }
            }
            k++;
