            k++;
          }
          if (k === template.length) {
            // Unclosed if statement
            throw new Error(`Unclosed if statement: ${tag}`);
          }
        }
      } else {
        // Handle regular tag
        result += data[tag] || '';
        i = j;
      }
    } else if (template[i] === '<' && template[i+1] === '/') {
      // Closing tag
      let j = i + 2;
      while (j < template.length && template[j] !== '>') {
        j++;
      }
      const tag = template.substring(i+2, j);

      if (tag === 'if') {
        // Handle if closing
        result += '';
        i = j;
      } else {
        // Handle regular closing tag
        if (tagStack.length === 0) {
          // Closing tag without matching opening tag
          throw new Error(`Unexpected closing tag: </${tag}>`);
        }
        const expectedTag = tagStack.pop();
        if (expectedTag !== tag) {
          // Mismatched closing tag
          throw new Error(`Mismatched closing tag: expected </${expectedTag}>, got </${tag}>`);
        }
        result += '';
        i = j;
      }
    } else {
      result += template[i];
      i++;
    }
  }

  // Check for unclosed opening tags
  if (tagStack.length > 0) {
    throw new Error(`Unclosed tag: <${tagStack[tagStack.length - 1]}>`);
  }

  return result;
}

